      assert.equal(result.value.dueDate, '2025-02-14');
    });

    it('calculates dueDate for NET14 (14 days after issue)', () => {
      const products = listProducts();
      const customers = listCustomers();
      const result = createInvoice({
        customerId: customers[0].id,
        issueDate: '2025-01-15',
        lines: [{ sku: products[0].sku, qty: 1 }],
        terms: 'NET14',
      });

      assert.equal(result.ok, true);
      assert.equal(result.value.terms, 'NET14');
      assert.equal(result.value.dueDate, '2025-01-29');
    });

    it('calculates dueDate for EOM (end of month)', () => {
      const products = listProducts();
      const customers = listCustomers();
      const result = createInvoice({
