      assert.equal(result.value.terms, 'EOM');
      assert.equal(result.value.dueDate, '2025-01-31');
    });

    it('calculates EOM correctly for last day of month', () => {
      const products = listProducts();
      const customers = listCustomers();
      const result = createInvoice({
        customerId: customers[0].id,
        issueDate: '2025-01-31',
        lines: [{ sku: products[0].sku, qty: 1 }],
        terms: 'EOM',
      });

      assert.equal(result.value.dueDate, '2025-01-31');
    });

    it('calculates EOM correctly across month boundary', () => {
      const products = listProducts();
      const customers = listCustomers();
      const result = createInvoice({
        customerId: customers[0].id,
        issueDate: '2025-01-30',
        lines: [{ sku: products[0].sku, qty: 1 }],
        terms: 'EOM',
      });

      assert.equal(result.value.dueDate, '2025-01-31');
    });

    it('calculates EOM correctly for February', () => {
      const products = listProducts();
      const customers = listCustomers();
