        customerId: customers[0].id,
        issueDate: '2025-02-10',
        lines: [{ sku: products[0].sku, qty: 1 }],
        terms: 'EOM',
      });

      assert.equal(result.value.dueDate, '2025-02-28');
    });

    it('calculates EOM correctly for leap year February', () => {
      const products = listProducts();
      const customers = listCustomers();
      const result = createInvoice({
        customerId: customers[0].id,
        issueDate: '2024-02-10',
        lines: [{ sku: products[0].sku, qty: 1 }],
        terms: 'EOM',
      });

      assert.equal(result.value.dueDate, '2024-02-29');
    });

    it('calculates EOM correctly at year boundary', () => {
      const products = listProducts();
      const customers = listCustomers();
      const result = createInvoice({
        customerId: customers[0].id,
        issueDate: '2025-12-15',
        lines: [{ sku: products[0].sku, qty: 1 }],
        terms: 'EOM',
      });

      assert.equal(result.value.dueDate, '2025-12-31');
    });

    it('rejects unknown terms', () => {
      const products = listProducts();
      const customers = listCustomers();
      const result = createInvoice({
        customerId: customers[0].id,
        issueDate: '2025-01-15',
        lines: [{ sku: products[0].sku, qty: 1 }],
        terms: 'NET45',
      });

      assert.equal(result.ok, false);
      assert.equal(result.error, 'TERMS_INVALID');
    });

    it('rejects empty string terms', () => {
      const products = listProducts();
      const customers = listCustomers();
      const result = createInvoice({
        customerId: customers[0].id,
        issueDate: '2025-01-15',
        lines: [{ sku: products[0].sku, qty: 1 }],
        terms: '',
      });

      assert.equal(result.ok, false);
      assert.equal(result.error, 'TERMS_INVALID');
    });

