import { describe, it } from 'node:test';
import { strict as assert } from 'node:assert';
import { createInvoice, lineTotal, lineDiscount, lineVAT, invoiceTotals, addLine, removeLine, issueInvoice } from '../src/invoices.js';
import { nextInvoiceNumber } from '../src/numbering.js';
import { listCustomers, TIER_DISCOUNTS, normalizeId } from '../src/customers.js';
import { listProducts } from '../src/catalogue.js';

describe('normalizeId', () => {
  it('trims whitespace', () => {
    assert.equal(normalizeId('  c-001  '), 'C-001');
  });

  it('converts to uppercase', () => {
    assert.equal(normalizeId('c-001'), 'C-001');
  });

  it('handles mixed case', () => {
    assert.equal(normalizeId('C-001'), 'C-001');
    assert.equal(normalizeId('c-001'), 'C-001');
    assert.equal(normalizeId('C-001'), 'C-001');
  });

  it('handles leading/trailing spaces', () => {
    assert.equal(normalizeId(' c-007 '), 'C-007');
    assert.equal(normalizeId('  C-002'), 'C-002');
    assert.equal(normalizeId('C-003  '), 'C-003');
  });

  it('handles null/undefined', () => {
    assert.equal(normalizeId(null), '');
    assert.equal(normalizeId(undefined), '');
  });

  it('combines case and whitespace handling', () => {
    assert.equal(normalizeId('  c-007 '), 'C-007');
    assert.equal(normalizeId(' C-001  '), 'C-001');
  });

  it('does not mutate the original', () => {
    const original = '  c-001  ';
    normalizeId(original);
    assert.equal(original, '  c-001  ');
  });
});

